#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
int main(int argc,char** argv){if(argc!=4)return 2;int n=std::atoi(argv[1]),k=std::atoi(argv[2]),reps=std::atoi(argv[3]);std::uint64_t sum=0;auto t=std::chrono::steady_clock::now();for(int i=0;i<reps;++i)for_each_combination<std::uint64_t>(n,k,[&](std::uint64_t m){sum+=m;});auto e=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(e-t).count()<<' '<<sum<<'\n';}
